"use strict";(globalThis.webpackChunkgrc||=[]).push([[98349],{19275(e){e.exports=JSON.parse('{"citeKey":"sun2001scalableparallel","slug":"sun-2001-scalable-parallel-bb68","title":"A Scalable Parallel Algorithm for Periodic Symmetric Toeplitz Tridiagonal Systems","authors":["X.-H. Sun"],"venue":"International Journal of Computer Research, Vol. 10, No. 1, 2001, pp. 89-98.","type":"Journal","entryType":"article","date":"January, 2001","year":2001,"era":"iit","month":1,"abstract":"Symmetric Toeplitz tridiagonal systems arise in many scientific applications. An efficient algorithm, the Simple Parallel Prefix (SPP) algorithm, was previously proposed for solving symmetric Toeplitz tridiagonal systems on SIMD and vector computers. Based on the SPP algorithm, a scalable parallel algorithm is proposed for solving periodic symmetric Toeplitz tridiagonal systems in this study. The newly proposed algorithm has the same parallel computation count as that of the SPP algorithm for non-periodic systems, and it requires only shift communication.","hasAbstract":true,"lede":"Symmetric Toeplitz tridiagonal systems arise in many scientific applications.","links":{"pdf":"https://grc.iit.edu/papers/2001/sun-2001-scalable-parallel-bb68.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","titleQualifier":"Journal 2001","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);